// models/index.ts
import { Injectable, InjectModel } from '@nestjs/mongodb';
import { Model } from 'mongoose';
import { Schema1, Schema2 } from './schemas';

@Injectable()
export class MyModelService {
  constructor(@InjectModel(Schema1.name) private readonly schema1Model: Model, @InjectModel(Schema2.name) private readonly schema2Model: Model) {}

  async createDocument(): Promise<any> {
    const schema1Doc = await this.schema1Model.create({ field1: 'example1', field2: 123 });
    const schema2Doc = await this.schema2Model.create({ field3: true, field4: new Date() });

    // Combine the documents into a single object
    const combinedDoc = { ...schema1Doc._doc, ...schema2Doc._doc };

    return combinedDoc;
  }
}
```

