    // Initial prices
    double carPriceInitial = 3000;
    double clothesPrice = 100;
    double bookPrice = 20;

    // Total price of clothes and book
    double totalClothesAndBookPrice = clothesPrice + bookPrice;

    // Check if the car price is at least double the combined price of the clothes and the book
    if (carPriceInitial <= totalClothesAndBookPrice * 2)
    {
        // Adjust the car price to meet the constraint
        carPriceInitial = totalClothesAndBookPrice * 2;
    }

    // Calculate the total cost of the purchase
    totalCost = carPriceInitial + totalClothesAndBookPrice;
}
```

To use this function, simply call it with two output parameters:

```csharp
double carPrice;
double totalCost;
CalculateTotalCost(out carPrice, out totalCost);
