function determineProtocol(inputData) {
  if (inputData.sourceIP && inputData.destinationIP && inputData.port) {
    // Check if the port number is within the range of UDP ports (1-65535)
    if (inputData.port >= 1 && inputData.port <= 65535) {
      return "UDP";
    }
  }
  return "HTTP";
}

