#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int main(int argc, char *argv[]) {
    char *cstr = (char *)malloc(sizeof(char) * (argc + 1));
    int i;

    for (i = 0; i < argc; i++) {
        strcat(cstr, argv[i]);
        if (i != argc - 1) {
            strcat(cstr, " ");
        }
    }
    cstr[argc] = '\0';

    printf("Converted string: %s\n", cstr);
    free(cstr);

