import { ExecutionContext, Injectable } from '@nestjs/common';
import { Observable } from 'rxjs';

@Injectable()
export class EnvCheckerDecorator {
  constructor(private readonly envService: EnvService) {}

  public use(middleware$: (...args: any[]) => Observable<any>): (...args: any[]) => Observable<any> {
    return async (...args: any[]): Promise<Observable<any>> => {
      const context = new ExecutionContext();
      context.switchToHttp().getRequest();

      const nodeEnv = this.envService.getNodeEnv();

      if (nodeEnv === 'true') {
        return middleware$(...args);
      } else {
        return Observable.create((observer) => observer.error('Not allowed in production environment.'));
      }
    };
  }
}
```

