```javascript
import React, { useState } from 'react';

const RemoveWidowsUtility = ({ text }) => {
  const [formattedText, setFormattedText] = useState(text);

  const handleRemoveWidows = () => {
    const words = formattedText.split(' ');
    const lastLine = [];

    for (let i = 0; i < words.length; i++) {
      const word = words[i];
      const lineBreak = /\n$/.test(word);

      if (!lineBreak) {
        lastLine.push(word);
      } else {
        setFormattedText(lastLine.join(' ') + '\n' + words.slice(i).join(' '));
        i--;
      }
    }
  };

  return (
    <div>
      <button onClick={handleRemoveWidows}>Remove Widows</button>
      <p>{formattedText}</p>
    </div>
  );
};

export default RemoveWidowsUtility;
```

To update your application without replacing the existing EXE, you can follow these steps:

1. Create a new folder in a temporary location to extract the update files.
2. Extract the contents of the ZIP file into the temporary folder.
3. Copy the updated DLLs and other necessary files from the temporary folder to the application's installation directory, overwriting the existing files.
4. Update the application's configuration file (e.g., app.config) with any new settings or configurations.
5. Restart the application to apply the updates.

Here's some sample code to demonstrate this process:
```csharp
using System;
using System.IO;
using System.Linq;
using System.Threading;

class Program
{
    static void Main(string[] args)
    {
        // Extract the update files to a temporary folder
        string tempFolder = Path.GetTempFileName();
        Directory.CreateDirectory(tempFolder);
        using (var zipFile = ZipFile.OpenRead("update.zip"))
        {
            zipFile.ExtractAll(tempFolder);
        }

        // Copy the updated files to the application's installation directory
        string installationDirectory = "C:\\Program Files\\MyApplication";
        foreach (string filePath in Directory.GetFiles(tempFolder))
        {
            string destinationFilePath = Path.Combine(installationDirectory, Path.GetFileName(filePath));
            if (!File.Exists(destinationFilePath))
            {
                File.Copy(filePath, destinationFilePath);
            }
        }

        // Update the application's configuration file
        string configFilePath = "C:\\Program Files\\MyApplication\\app.config";
        if (File.Exists(configFilePath))
        {
            string newConfigContent = File.ReadAllText(configFilePath);
            // Add any new settings or configurations here
            File.WriteAllText(configFilePath, newConfigContent);
        }

        // Restart the application
        Process.Start("myapplication.exe");
    }
}
```
