const { Redis } = require("ioredis");

class RedisClient {
  constructor() {
    this.redis = new Redis({
      host: "localhost",
      port: 6379,
      password: "your_password",
    });

    this.redis.on("error", (err) => {
      console.error("Error with Redis:", err);
    });
  }

  async isAlive() {
    try {
      await this.redis.ping();
      return true;
    } catch (error) {
      return false;
    }
  }

  async get(key) {
    try {
      const value = await this.redis.get(key);
      return value;
    } catch (error) {
      throw new Error(`Error getting value from Redis: ${key}`);
    }
  }

  async set(key, value, duration) {
    try {
      await this.redis.set(key, value, "EX", duration);
    } catch (error) {
      throw new Error(`Error setting value in Redis: ${key}`);
    }
  }

  async del(key) {
    try {
      await this.redis.del(key);
    } catch (error) {
      throw new Error(`Error deleting value in Redis: ${key}`);
    }
  }
}

const redisClient = new RedisClient();
module.exports = redisClient;
```

